t.script:
(function () {
    var list = document.getElementById('exp-list');
    var wrap = document.getElementById('exp-template-wrap');
    var addBtn = document.getElementById('exp-add');
    if (!list || !wrap || !addBtn) { return; }
    function bindRemove(scope) {
        scope.querySelectorAll('.exp-remove').forEach(function (btn) {
            btn.onclick = function () {
                var item = btn.closest('.exp-item');
                if (item) { item.remove(); }
            };
        });
    }
    addBtn.addEventListener('click', function () {
        var node = wrap.firstElementChild.cloneNode(true);
        node.querySelectorAll('input').forEach(function (inp) {
            inp.setAttribute('required', 'required');
        });
        list.appendChild(node);
        bindRemove(node);
    });
    bindRemove(list);
})();

(function () {
    var list = document.getElementById('autre-doc-list');
    var wrap = document.getElementById('autre-doc-template-wrap');
    var addBtn = document.getElementById('autre-doc-add');
    if (!list || !wrap || !addBtn) { return; }
    function bindRemove(scope) {
        scope.querySelectorAll('.autre-doc-remove').forEach(function (btn) {
            btn.onclick = function () {
                var item = btn.closest('.autre-doc-item');
                if (item) { item.remove(); }
            };
        });
    }
    addBtn.addEventListener('click', function () {
        var node = wrap.firstElementChild.cloneNode(true);
        list.appendChild(node);
        bindRemove(node);
    });
    var existing = document.getElementById('autre-doc-existing');
    if (existing) {
        existing.querySelectorAll('.autre-doc-remove-existing').forEach(function (btn) {
            btn.onclick = function () {
                var li = btn.closest('.list-group-item');
                if (li) { li.remove(); }
            };
        });
    }
})();
